// Generated by the Nikaia bootstrap compiler (Stage 0).
// Edit order.nika in the directory above, not this file.

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Operation {
    pub binds: Option<String>,
    pub mentions: collections::BTreeSet<String>,
    pub reaches: Vec<Reached>,
    pub callee: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Accounted {
    Operation(Operation),
    NotAnOperation,
    Opaque(String),
    DivertingHandler,
    UncaughtFailure(String),
    NoTouches(String),
    UnknownResource { callee: String, kind: String },
    MayNotCross { callee: String, crossing: Crossing },
    NonLiteralArgument(String),
}

impl Accounted {
    pub fn why(&self) -> String {
        match self {
            Accounted::Operation(_) => String::from("it is an operation"),
            Accounted::NotAnOperation => String::from("one of them performs no operation at all"),
            Accounted::Opaque(what) => format!("one of them holds {}", what),
            Accounted::DivertingHandler => String::from("its `catch` can leave the function, so the next statement might never run. Make the handler return a value instead, and check it afterwards"),
            Accounted::UncaughtFailure(name) => format!("`{}` can fail and nothing catches it, so the next statement might never run. `catch` it into a value, and check it afterwards", name),
            Accounted::NoTouches(name) => format!("nothing says what `{}` touches, so it might touch anything", name),
            Accounted::UnknownResource { callee, kind } => unknown_resource(callee, kind),
            Accounted::MayNotCross { callee, crossing } => may_not_cross(callee, crossing),
            Accounted::NonLiteralArgument(name) => format!("`{}` isn't a literal, and only literals can be sent to another thread", name),
        }
    }
}

pub(crate) fn unknown_resource(callee: &str, kind: &str) -> String {
    let article = an_or_a(kind);
    format!("`{}` says it touches {} `{}`, which this version of Nikaia doesn't know, so it might touch anything", callee, article, kind)
}

pub(crate) fn may_not_cross(callee: &str, crossing: &Crossing) -> String {
    let note = nikaia_std::index::or(crossing.note(), || "It can't.".into());
    format!("what `{}` returns would have to move to another thread. {}", callee, note)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Verdict {
    Overlap,
    DataDependency(String),
    Shadowed(String),
    SameResource { kind: String, named: Option<String>, unnameable: bool },
    SameDestination { one: String, other: String },
    NotAccountedFor,
}

impl Verdict {
    pub fn is_overlap(&self) -> bool { matches!(self, Verdict::Overlap) }
    pub fn why(&self) -> String {
        match self {
            Verdict::Overlap => String::from("they meet on nothing"),
            Verdict::DataDependency(name) => format!("the second uses `{}`", name),
            Verdict::Shadowed(name) => format!("both bind `{}`", name),
            Verdict::SameResource { kind, named, unnameable } => { let unnameable = *unnameable; same_resource(kind, (named).as_deref(), unnameable) },
            Verdict::SameDestination { one, other } => format!("one touches {} and the other {}, which might be the same place. Use `seq` to run them in order", one, other),
            Verdict::NotAccountedFor => String::from("the compiler can't tell what one of them does"),
        }
    }
}

pub(crate) fn same_resource(kind: &str, named: Option<&str>, unnameable: bool) -> String {
    if named.is_some() {
        let name = nikaia_std::index::or(named, || "");
        return format!("both reach {} `{}`, and one writes it", kind, name);
    }
    if unnameable { return format!("both touch a {} the compiler can't name, and one writes to it", kind); }
    format!("both touch {}, and one writes to it", kind)
}

pub fn verdict(earlier: &Operation, later: &Operation) -> Verdict {
    let bound = written_or_nothing((earlier.binds).as_deref());
    if earlier.binds.is_some() && later.mentions.contains(&bound) { return Verdict::DataDependency(bound.to_owned()); }
    if earlier.binds.is_some() && earlier.binds == later.binds { return Verdict::Shadowed(bound.to_owned()); }
    for a in earlier.reaches.iter() { for b in later.reaches.iter() { if a.conflicts_with(b) { return conflict(a, b); } } }
    Verdict::Overlap
}

pub(crate) fn conflict(a: &Reached, b: &Reached) -> Verdict {
    if a.kind != b.kind { return Verdict::SameDestination { one: a.kind.to_owned(), other: b.kind.to_owned() }; }
    let named = match readable_name(a) { Some(__nikaia_value) => __nikaia_value, None => match readable_name(b) { Some(__nikaia_value) => __nikaia_value, None => return Verdict::SameResource { kind: a.kind.to_owned(), named: None, unnameable: a.unknown || b.unknown } } };
    Verdict::SameResource { kind: a.kind.to_owned(), named: Some(named), unnameable: false }
}

pub(crate) fn readable_name(reached: &Reached) -> Option<String> {
    if reached.unknown { return None; }
    match reached.named.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

pub fn group_verdict(run: &[Operation]) -> Verdict {
    for i in 0..run.len() as i64 {
        for j in i + 1..run.len() as i64 {
            let found = verdict(nikaia_std::index::get(&run, (i) as usize), nikaia_std::index::get(&run, nikaia_std::index::at(j)));
            if !found.is_overlap() { return found; }
        }
    }
    Verdict::Overlap
}

pub fn group_of(run: &[Operation]) -> i64 {
    let mut taken: i64 = if !run.is_empty() { 1 } else { 0 };
    while taken < run.len() as i64 {
        if !fits_with_the_front(run, taken) { break; }
        taken += 1;
    }
    if taken < 2 { return 0; }
    taken
}

pub(crate) fn fits_with_the_front(run: &[Operation], at: i64) -> bool {
    for i in 0..at { if !verdict(nikaia_std::index::get(&run, (i) as usize), nikaia_std::index::get(&run, nikaia_std::index::at(at))).is_overlap() { return false; } }
    true
}

pub(crate) const KNOWN_KINDS: [&str; 6] = ["file", "stdout", "stderr", "args", "lock", "socket"];

pub fn accounted(stmt: &Stmt, words: &winnow_grammar::InternerContext, walking: &Walking<'_, '_>) -> Accounted {
    match stmt {
        Stmt::Let { names, value, ty, .. } => {
            if ty.is_some() { return Accounted::Opaque(String::from("a written type, which would have to be carried onto one half of a pattern")); }
            if names.len() != 1 { return Accounted::Opaque(String::from("several names bound at once")); }
            let binds: Option<String> = Some(words.resolve(*nikaia_std::index::get(&names, 0)).to_owned());
            accounted_value(binds, value, words, walking)
        },
        Stmt::Expr(value) => accounted_value(None, value, words, walking),
        _ => Accounted::NotAnOperation,
    }
}

pub(crate) fn accounted_value(binds: Option<String>, value: &Expr, names: &winnow_grammar::InternerContext, walking: &Walking<'_, '_>) -> Accounted {
    match value {
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            if diverts_within(&handler.stmts, false) { return Accounted::DivertingHandler; }
            let mut reduced = Reduced { calls: vec![], performs: false, methods: vec![], refused: None };
            reduce(expr, names, &mut reduced);
            reduce_handler(handler, names, &mut reduced);
            let mut mentions: collections::BTreeSet<String> = collections::BTreeSet::new();
            names_in(expr, names, &mut mentions);
            names_in_block(handler, names, &mut mentions);
            accounted_reduced(binds, mentions, &reduced, true, walking)
        },
        _ => {
            let mut reduced = Reduced { calls: vec![], performs: false, methods: vec![], refused: None };
            reduce(value, names, &mut reduced);
            let mut mentions: collections::BTreeSet<String> = collections::BTreeSet::new();
            names_in(value, names, &mut mentions);
            accounted_reduced(binds, mentions, &reduced, false, walking)
        },
    }
}

pub(crate) fn accounted_reduced(binds: Option<String>, mentions: collections::BTreeSet<String>, reduced: &Reduced, caught: bool, walking: &Walking<'_, '_>) -> Accounted {
    if reduced.calls.is_empty() && !reduced.performs { return Accounted::NotAnOperation; }
    let mut reaches: Vec<Reached> = vec![];
    let mut named_by: Vec<String> = vec![];
    for call in reduced.calls.iter() {
        let refused = a_call_reaches(call, caught, walking, &mut reaches, &mut named_by);
        if refused.is_some() { return nikaia_std::index::or(refused, || Accounted::NotAnOperation); }
    }
    for method in reduced.methods.iter() { if !reaches_nothing(method, walking) { return Accounted::NoTouches(method.to_owned()); } }
    if reduced.refused.is_some() {
        return nikaia_std::index::or(match reduced.refused.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || Accounted::NotAnOperation);
    }
    Accounted::Operation(Operation { binds, mentions, reaches, callee: named_by.join(" + ") })
}

pub(crate) fn a_call_reaches(call: &OneCall, caught: bool, walking: &Walking<'_, '_>, reaches: &mut Vec<Reached>, named_by: &mut Vec<String>) -> Option<Accounted> {
    let key = call.key.to_owned();
    let contract = match touches_described(&key, walking) { Some(__nikaia_value) => __nikaia_value, None => return Some(Accounted::NoTouches(key)) };
    if !caught && !contract.fails_with.is_empty() { return Some(Accounted::UncaughtFailure(key)); }
    for touch in contract.touches.iter() { if !known_kind(&touch.kind) { return Some(Accounted::UnknownResource { callee: key.to_owned(), kind: touch.kind.to_owned() }); } }
    let signature = match match contract.signature.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return Some(Accounted::NoTouches(key)) };
    let crossed = crossing(&signature.result_or_unit(), walking);
    if !crossed.may() { return Some(Accounted::MayNotCross { callee: key.to_owned(), crossing: crossed }); }
    let parameters = call_parameters(&signature);
    for touch in contract.touches.iter() {
        let named = argument_named((touch.parameter).as_deref(), &parameters, &call.arguments);
        reaches.push(Reached { kind: touch.kind.to_owned(), unknown: touch.parameter.is_some() && named.is_none(), named, write: touch.write });
    }
    named_by.push(key);
    None
}

pub(crate) fn touches_described(key: &str, walking: &Walking<'_, '_>) -> Option<FnContract> {
    let mine: Option<FnContract> = match *nikaia_std::index::get(&walking.own.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    let found = match mine { Some(__nikaia_value) => __nikaia_value, None => match match *nikaia_std::index::get(&walking.library.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return None } };
    if !found.touches_known { return None; }
    Some(found)
}

pub(crate) fn known_kind(kind: &str) -> bool {
    for known in KNOWN_KINDS.iter() {
        let known = *known;
        if known == kind { return true; }
    }
    false
}

pub(crate) fn call_parameters(signature: &Signature) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for i in 0..signature.params.len() as i64 { if i > 0 || nikaia_std::index::get(&signature.params, (i) as usize).0 != "self" { out.push(nikaia_std::index::get(&signature.params, (i) as usize).0.to_owned()); } }
    out
}

pub(crate) fn argument_named(parameter: Option<&str>, parameters: &[String], arguments: &[Expr]) -> Option<String> {
    let wanted = match parameter { Some(__nikaia_value) => __nikaia_value, None => return None };
    for at in 0..parameters.len() as i64 {
        if *nikaia_std::index::get(&parameters, (at) as usize) == wanted {
            if ((at) as usize) >= arguments.len() { return None; }
            return literal_text(nikaia_std::index::get(&arguments, (at) as usize));
        }
    }
    None
}

pub(crate) fn literal_text(expr: &Expr) -> Option<String> {
    match expr {
        Expr::LitStr { text, .. } => Some(text.to_owned()),
        _ => None,
    }
}

pub(crate) fn reaches_nothing(method: &str, walking: &Walking<'_, '_>) -> bool {
    let mut candidates = method_entries(method, walking.own);
    if candidates.is_empty() { candidates = method_entries(method, walking.library); }
    if candidates.is_empty() { return false; }
    for contract in candidates.iter() { if !contract.touches_known || !contract.touches.is_empty() { return false; } }
    true
}

pub(crate) fn method_entries(method: &str, ledger: &Ledger) -> Vec<FnContract> {
    let suffix = format!("::{}", method);
    let mut out: Vec<FnContract> = vec![];
    for (key, contract) in ledger.functions.iter() { if key.ends_with(&suffix) && takes_a_subject((contract.signature).as_ref()) { out.push(contract.clone()); } }
    out
}

pub(crate) fn takes_a_subject(signature: Option<&Signature>) -> bool {
    let written = match signature { Some(__nikaia_value) => __nikaia_value, None => return true };
    written.takes_a_receiver()
}

#[derive(Debug, Clone, PartialEq)]
pub struct OneCall {
    pub key: String,
    pub arguments: Vec<Expr>,
}

#[derive(Debug, Clone, PartialEq)]
pub(crate) struct Reduced {
    pub(crate) calls: Vec<OneCall>,
    pub(crate) performs: bool,
    pub(crate) methods: Vec<String>,
    pub(crate) refused: Option<Accounted>,
}

pub(crate) fn noted(reduced: &mut Reduced, why: Accounted) { if reduced.refused.is_none() { reduced.refused = Some(why); } }

pub(crate) fn stopped(reduced: &mut Reduced, why: Accounted) {
    reduced.performs = true;
    noted(reduced, why);
}

pub(crate) fn reduce_handler(block: &Block, names: &winnow_grammar::InternerContext, reduced: &mut Reduced) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { value, .. } => { reduce(value, names, reduced); },
            Stmt::Expr(value) => { reduce(value, names, reduced); },
            _ => { stopped(reduced, Accounted::Opaque(String::from("a `catch` handler doing more than handing back a value"))); },
        }
    }
}

pub(crate) fn reduce(node: &Expr, names: &winnow_grammar::InternerContext, reduced: &mut Reduced) {
    match node {
        Expr::LitInt { .. } => { },
        Expr::LitFloat(_, _) => { },
        Expr::LitBool(_, _) => { },
        Expr::LitNull(_) => { },
        Expr::LitChar(_, _) => { },
        Expr::LitStr { .. } => { },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            if !config.is_empty() {
                stopped(reduced, Accounted::Opaque(String::from("a call with options, which nothing matches against the callee's order yet")));
                return;
            }
            let key = match called_key(func, names) { Some(__nikaia_value) => __nikaia_value, None => return stopped(reduced, Accounted::Opaque(String::from("a call through something that is not a name"))) };
            for arg in args.iter() { reduce(arg, names, reduced); }
            reduced.calls.push(OneCall { key, arguments: args.to_owned() });
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); reduce(expr, names, reduced); },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); reduce(expr, names, reduced); },
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            if a_short_circuit(op) {
                stopped(reduced, Accounted::Opaque(String::from("a `&&` or `||`, whose right side runs only sometimes")));
                return;
            }
            reduce(lhs, names, reduced);
            reduce(rhs, names, reduced);
        },
        Expr::Tuple(parts, _) => { for part in parts.iter() { reduce(part, names, reduced); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { reduce(item, names, reduced); } },
        Expr::Return(_, _) => { stopped(reduced, Accounted::Opaque(String::from("a `return`, a `break` or a `continue`"))); },
        Expr::Break(_) => { stopped(reduced, Accounted::Opaque(String::from("a `return`, a `break` or a `continue`"))); },
        Expr::Continue(_) => { stopped(reduced, Accounted::Opaque(String::from("a `return`, a `break` or a `continue`"))); },
        Expr::Variable(name, _) => { let name = *name; noted(reduced, Accounted::NonLiteralArgument(names.resolve(name).to_owned())); },
        Expr::Field { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(base, names, reduced);
        },
        Expr::SafeField { base, .. } => {
            let base = nikaia_std::boxed::open(base);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(base, names, reduced);
        },
        Expr::Index { base, index, .. } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(base, names, reduced);
            reduce(index, names, reduced);
        },
        Expr::Path(_, _) => { },
        Expr::StructLit { fields, .. } => {
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            for field in fields.iter() { reduce_maybe((field.value).as_ref(), names, reduced); }
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            noted(reduced, Accounted::Opaque(String::from("a value read from somewhere else")));
            reduce(start, names, reduced);
            reduce(end, names, reduced);
        },
        Expr::Coalesce { value, fallback, .. } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            noted(reduced, Accounted::Opaque(String::from("a `??`, whose fallback runs only sometimes")));
            reduce(value, names, reduced);
            reduce(fallback, names, reduced);
        },
        Expr::LitInterpolated { .. } => { stopped(reduced, Accounted::Opaque(String::from("text with code in it, whose holes this has not parsed"))); },
        Expr::MethodCall { receiver, method, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; reduce_method(receiver, method, args, config, names, reduced); },
        Expr::SafeMethod { receiver, method, args, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; reduce_method(receiver, method, args, config, names, reduced); },
        Expr::Closure { .. } => { stopped(reduced, Accounted::Opaque(String::from("a lambda, whose body this analysis does not read"))); },
        _ => { stopped(reduced, Accounted::Opaque(String::from("something with its own control flow"))); },
    }
}

pub(crate) fn reduce_method(receiver: &Expr, method: winnow_grammar::Symbol, args: &[Expr], config: &[ConfigArg], names: &winnow_grammar::InternerContext, reduced: &mut Reduced) {
    reduce(receiver, names, reduced);
    for arg in args.iter() { reduce(arg, names, reduced); }
    for option in config.iter() { reduce(&option.value, names, reduced); }
    reduced.methods.push(names.resolve(method).to_owned());
}

pub(crate) fn reduce_maybe(expr: Option<&Expr>, names: &winnow_grammar::InternerContext, reduced: &mut Reduced) { reduce(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, names, reduced); }

pub(crate) fn a_short_circuit(op: &BinaryOp) -> bool { matches!(op, BinaryOp::And | BinaryOp::Or) }

pub(crate) fn called_key(func: &Expr, names: &winnow_grammar::InternerContext) -> Option<String> {
    match func {
        Expr::Variable(name, _) => { let name = *name; Some(names.resolve(name).to_owned()) },
        Expr::Path(segments, _) => Some(joined_segments(segments, names)),
        _ => None,
    }
}

pub(crate) fn joined_segments(segments: &[winnow_grammar::Symbol], names: &winnow_grammar::InternerContext) -> String {
    let mut parts: Vec<String> = vec![];
    for segment in segments.iter() {
        let segment = *segment;
        parts.push(names.resolve(segment).to_owned());
    }
    parts.join("::")
}

pub fn diverts_within(stmts: &[Spanned<Stmt>], bound: bool) -> bool {
    for stmt in stmts.iter() {
        let leaves = match &stmt.node {
            Stmt::Return(_) => true,
            Stmt::Break => !bound,
            Stmt::Continue => !bound,
            Stmt::Expr(expr) => holds_throw(expr, bound),
            Stmt::Let { value, .. } => holds_throw(value, bound),
            Stmt::Comptime { value, .. } => holds_throw(value, bound),
            Stmt::Assign { value, .. } => holds_throw(value, bound),
            Stmt::For { body, .. } => diverts_within(&body.stmts, true),
            Stmt::While { body, .. } => diverts_within(&body.stmts, true),
        };
        if leaves { return true; }
    }
    false
}

pub(crate) fn holds_throw(expr: &Expr, bound: bool) -> bool {
    match expr {
        Expr::Throw(_, _) => true,
        Expr::Block(block, _) => diverts_within(&block.stmts, bound),
        Expr::Overlap(block, _) => diverts_within(&block.stmts, bound),
        Expr::If { then_branch, else_branch, .. } => diverts_within(&then_branch.stmts, bound) || else_diverts((else_branch).as_ref(), bound),
        Expr::Match { arms, .. } => an_arm_throws(arms, bound),
        _ => false,
    }
}

pub(crate) fn else_diverts(block: Option<&Block>, bound: bool) -> bool {
    let written = match block { Some(__nikaia_value) => __nikaia_value, None => return false };
    diverts_within(&written.stmts, bound)
}

pub(crate) fn an_arm_throws(arms: &[MatchArm], bound: bool) -> bool {
    for arm in arms.iter() { if holds_throw(&arm.body, bound) { return true; } }
    false
}

pub fn overlap_report(items: &[Spanned<Item>], names: &winnow_grammar::InternerContext, walking: &Walking<'_, '_>, overlaps_in: &impl Fn(&Block) -> Vec<Block>, pauses: &impl Fn(&Spanned<Stmt>) -> bool) -> String {
    let mut out: String = String::from("");
    for item in items.iter() {
        match &item.node {
            Item::Fn { .. } => { block_report(&item.node, None, names, walking, overlaps_in, pauses, &mut out); },
            Item::Impl { target, methods, .. } => {
                let owner: Option<String> = Some(names.resolve(target.name).to_owned());
                for method in methods.iter() { block_report(&method.node, (owner).as_deref(), names, walking, overlaps_in, pauses, &mut out); }
            },
            _ => { },
        }
    }
    if out.is_empty() { out.push_str("this program writes no `overlap { … }` block.\n"); }
    out
}

pub(crate) fn block_report(item: &Item, target: Option<&str>, names: &winnow_grammar::InternerContext, walking: &Walking<'_, '_>, overlaps_in: &impl Fn(&Block) -> Vec<Block>, pauses: &impl Fn(&Spanned<Stmt>) -> bool, out: &mut String) {
    match item {
        Item::Fn { name, body, .. } => {
            let name = *name;
            let own_name = function_name(names, name);
            let key = keyed(target, &own_name);
            for block in overlaps_in(body) { one_block_report(&key, &block, names, walking, pauses, out); }
        },
        _ => { },
    }
}

pub(crate) fn keyed(target: Option<&str>, own_name: &str) -> String {
    let owner = match target { Some(__nikaia_value) => __nikaia_value, None => return own_name.to_owned() };
    format!("{}::{}", owner, own_name)
}

pub(crate) fn one_block_report(key: &str, block: &Block, names: &winnow_grammar::InternerContext, walking: &Walking<'_, '_>, pauses: &impl Fn(&Spanned<Stmt>) -> bool, out: &mut String) {
    if block.stmts.is_empty() { return; }
    let mut operations: Vec<Operation> = vec![];
    let mut present: Vec<bool> = vec![];
    let mut lines: Vec<String> = vec![];
    for stmt in block.stmts.iter() {
        let answer = accounted(&stmt.node, names, walking);
        let named = match answer {
            Accounted::Operation(ref operation) => operation.callee.to_owned(),
            _ => String::from("…"),
        };
        match answer {
            Accounted::Operation(ref operation) => {
                operations.push(operation.clone());
                present.push(true);
            },
            _ => {
                operations.push(Operation { binds: None, mentions: collections::BTreeSet::new(), reaches: vec![], callee: String::from("") });
                present.push(false);
            },
        }
        let when = if pauses(stmt) { "started first" } else { "runs while they wait" };
        lines.push(format!("    {} {}", padded_right(when, 22), named));
    }
    let count = block.stmts.len() as i64;
    let refused = first_refused(&operations, &present);
    if refused.is_empty() { out.push_str(&format!("{}: an `overlap` of {} branches, which meet on nothing\n", key, count)); } else { out.push_str(&refused_header(key, count, &operations, &refused)); }
    for line in lines.iter() {
        out.push_str(line);
        out.push('\n');
    }
}

pub(crate) fn first_refused(operations: &[Operation], present: &[bool]) -> Vec<i64> {
    for i in 0..operations.len() as i64 { for j in i + 1..operations.len() as i64 { if *nikaia_std::index::get(&present, (i) as usize) && *nikaia_std::index::get(&present, nikaia_std::index::at(j)) && !verdict(nikaia_std::index::get(&operations, (i) as usize), nikaia_std::index::get(&operations, nikaia_std::index::at(j))).is_overlap() { return vec![i, j]; } } }
    vec![]
}

pub(crate) fn refused_header(key: &str, count: i64, operations: &[Operation], pair: &[i64]) -> String {
    let first = *nikaia_std::index::get(&pair, 0) + 1;
    let second = *nikaia_std::index::get(&pair, 1) + 1;
    let why = verdict(nikaia_std::index::get(&operations, nikaia_std::index::at(*nikaia_std::index::get(&pair, 0))), nikaia_std::index::get(&operations, nikaia_std::index::at(*nikaia_std::index::get(&pair, 1)))).why();
    format!("{}: an `overlap` of {} branches, and branches {} and {} may not run together - {}\n", key, count, first, second, why)
}

pub(crate) fn padded_right(text: &str, width: i64) -> String {
    let mut out = text.to_owned();
    let mut have = text.chars().count() as i64;
    while have < width {
        out.push(' ');
        have += 1;
    }
    out
}

